import { DatabaseSync } from 'node:sqlite'
import { readFileSync, readdirSync } from 'node:fs'
import { join, dirname } from 'node:path'
import { fileURLToPath } from 'node:url'

const MIGRATIONS_DIR = join(dirname(fileURLToPath(import.meta.url)), 'migrations')

let instance: DatabaseSync | null = null

/** Menjalankan migrasi yang belum diterapkan, berurutan menurut nama file. */
export function migrate(db: DatabaseSync): void {
  db.exec('CREATE TABLE IF NOT EXISTS schema_migrations (name TEXT PRIMARY KEY)')
  const rows = db.prepare('SELECT name FROM schema_migrations').all() as { name: string }[]
  const applied = new Set(rows.map((r) => r.name))

  const files = readdirSync(MIGRATIONS_DIR)
    .filter((f) => f.endsWith('.sql'))
    .sort()

  for (const file of files) {
    if (applied.has(file)) continue
    db.exec('BEGIN')
    try {
      db.exec(readFileSync(join(MIGRATIONS_DIR, file), 'utf8'))
      db.prepare('INSERT INTO schema_migrations (name) VALUES (?)').run(file)
      db.exec('COMMIT')

      // Diperiksa SESUDAH commit, dan sengaja: `foreign_key_check` hanya
      // melaporkan, tidak menolak, dan sebagian migrasi (mis. 002_auth)
      // memang harus mematikan `foreign_keys` untuk bisa membangun ulang
      // tabel tanpa CASCADE menghapus tabel anak. Yang dijaga di sini adalah
      // hasil akhirnya: kalau rebuild meninggalkan baris anak yang menunjuk
      // ke induk yang tidak ada lagi, migrasi berikutnya tidak boleh jalan di
      // atas database yang sudah rusak.
      const menggantung = db.prepare('PRAGMA foreign_key_check').all()
      if (menggantung.length > 0) {
        throw new Error(
          `Migrasi ${file} meninggalkan ${menggantung.length} referensi menggantung. ` +
            `Database sudah ter-commit dan HARUS dipulihkan dari backup. ` +
            `Contoh: ${JSON.stringify(menggantung[0])}`,
        )
      }
    } catch (err) {
      // ROLLBACK sendiri bisa melempar bila file migrasi memuat COMMIT-nya
      // sendiri sehingga tidak ada lagi transaksi aktif. Kalau itu dibiarkan,
      // error rollback menggantikan penyebab aslinya dan migrasi jadi mustahil
      // didiagnosis. Penyebab asli selalu menang.
      try {
        db.exec('ROLLBACK')
      } catch {
        // sengaja diabaikan
      }
      throw err
    }
  }
}

/** Membuka database pada path tertentu dan memastikan skemanya mutakhir. */
export function openDb(path: string): DatabaseSync {
  const db = new DatabaseSync(path)
  // busy_timeout WAJIB lebih dulu. Tanpa ini koneksi kedua langsung gagal
  // "database is locked" alih-alih menunggu giliran — dan `journal_mode = WAL`
  // di bawah sendiri mengambil kunci eksklusif, jadi kalau urutannya dibalik
  // dua proses yang menyala bersamaan saling menjatuhkan sebelum timeout ini
  // sempat berlaku. Terukur ~22% kegagalan start pada 3 proses serentak.
  db.exec('PRAGMA busy_timeout = 5000')
  if (path !== ':memory:') db.exec('PRAGMA journal_mode = WAL')
  db.exec('PRAGMA foreign_keys = ON')
  migrate(db)
  return db
}

/** Koneksi bersama untuk aplikasi. Test memakai openDb(':memory:') sendiri. */
export function getDb(): DatabaseSync {
  if (!instance) instance = openDb(process.env.DB_PATH ?? 'data.db')
  return instance
}

export function closeDb(): void {
  instance?.close()
  instance = null
}
